import numpy as np
from PIL import Image
from collections import deque
im=np.array(Image.open('first_frame.png').convert('RGB'))
# print RGB samples on grid
for y in range(0,144,8):
  print('\\ny=',y)
  for x in range(80,201,8):
    r,g,b=im[y,x]
    print(f'{x:3d}:({r:3d},{g:3d},{b:3d})',end=' ')
  print()
# masks and connected components bboxes
def comps(mask, minsize=5):
    h,w=mask.shape; seen=np.zeros_like(mask,bool); out=[]
    for yy,xx in zip(*np.where(mask & ~seen)):
        q=[(yy,xx)]; seen[yy,xx]=1; n=0; minx=maxx=xx; miny=maxy=yy; sx=sy=0
        for cy,cx in q:
          n+=1; sx+=cx; sy+=cy
          for dy in (-1,0,1):
           for dx in (-1,0,1):
            if dy==0 and dx==0: continue
            ny,nx=cy+dy,cx+dx
            if 0<=ny<h and 0<=nx<w and mask[ny,nx] and not seen[ny,nx]:
              seen[ny,nx]=1;q.append((ny,nx));minx=min(minx,nx);maxx=max(maxx,nx);miny=min(miny,ny);maxy=max(maxy,ny)
        if n>=minsize: out.append((n,(minx,miny,maxx,maxy),(sx//n,sy//n)))
    return sorted(out, reverse=True)
r,g,b=[im[...,i].astype(int) for i in range(3)]
masks={
'blue_strong': (b>r+15)&(b>g+5)&(b>25),
'blue_any': (b>r+5)&(b>=g),
'dark': (im.max(2)<65),
'white': (im.min(2)>175),
'lightgray': (im.min(2)>130)&(im.max(2)<230),
'redwood': (r>g+25)&(g>b+10)&(r>80),
}
for name,m in masks.items():
 print('\\n',name,m.sum())
 for c in comps(m,10)[:20]: print(c)
PY"
